with joined as (select a.id, a.session_id, a.event_type, a.event_time, a.duration_sec, d.browser, d.country from web_events a left join sessions d on a.session_id = d.id where d.country in ('SG', 'US')), cleaned as (select *, ceil(duration_sec) as duration_sec_whole, initcap(trim(browser)) as browser_title, coalesce(browser, 'DIRECT') as resolved_browser from joined where event_time > to_date('2023-04-27')), enriched as (select s.*, p.country as session_country, p.browser as session_browser, p.device from cleaned s left join sessions p on s.session_id = p.id), scored as (select id, session_id, event_type, event_time, country, browser_title, resolved_browser, session_country, avg(duration_sec) over (partition by event_type, browser order by duration_sec_whole asc, id asc rows between 2 preceding and 1 preceding) as duration_sec_avg_2_prior, first_value(session_browser) ignore nulls over (partition by session_browser order by duration_sec_whole asc, id asc rows between unbounded preceding and current row) as first_known_session_browser, lead(duration_sec, 1) over (partition by month(event_time), session_browser order by duration_sec asc, id asc) as next_duration_sec, avg(duration_sec) over (partition by session_id order by duration_sec asc, id asc rows between 5 preceding and 1 preceding) as duration_sec_avg_5_prior from enriched), pivoted as (select * from (select session_id, country, duration_sec_avg_5_prior from scored) src pivot (sum(duration_sec_avg_5_prior) as amount, count(1) as item_count for country in ('SG', 'US'))) select s.session_id, s.SG_amount, s.US_item_count, (select min(w2.duration_sec) from web_events w2 where w2.session_id = s.session_id) as min_web_event_duration_sec from pivoted s order by SG_amount asc nulls last;
